const rows = $input.first().json.data;
const siteUrl = rows.find(r => r[0] === 'gsc_site_url')?.[1] || '';
const saEmail = rows.find(r => r[0] === 'gsc_service_account_email')?.[1] || '';
const saKey = rows.find(r => r[0] === 'gsc_service_account_key')?.[1] || '';
if (!siteUrl) throw new Error('GSC site URL not configured');
return [{
  json: {
    site_url: siteUrl,
    sa_email: saEmail,
    sa_key: saKey
  }
}];

const input = $input.first().json;
const cfg = $input.first().json;
const postUrl = input.post_url || input.postUrl || '';
if (!postUrl) throw new Error('No post_url provided for indexing');
return [{
  json: {
    url: postUrl,
    type: 'URL_UPDATED',
    site_url: cfg.site_url
  }
}];

const resp = $input.first().json;
return [{
  json: {
    notification_url: resp.urlNotificationMetadata?.url || '',
    status: resp.urlNotificationMetadata?.latestUpdate?.type || 'UNKNOWN',
    notify_time: resp.urlNotificationMetadata?.latestUpdate?.notifyTime || '',
    step: '6A',
    post_url: $input.first().json.url
  }
}];

return [{
  json: {
    index_status: $input.first().json.status,
    post_url: $input.first().json.post_url,
    status: 'done',
    step: '6A'
  }
}];
